    "question": "How do you manage Conversation History without running out of tokens?",
    "answer": "Because HTTP is stateless, the frontend or backend resends history on each turn. To prevent context overflow and ballooning costs: 1) Sliding Window: Retain only the last N messages (e.g. last 6-8 messages), 2) Conversation Summarization: Periodically summarize older messages into a 2-sentence context recap, and 3) Prune system messages to avoid redundancy.",
