    "question": "How does Streaming work under the hood in LLM APIs?",
    "answer": "When `stream: true` is set, the API does not wait for full text generation. Instead, it leaves the HTTP connection open using chunked transfer encoding (`Transfer-Encoding: chunked`) and emits Server-Sent Events (SSE) containing token deltas as they are generated. The web server forwards these chunks directly to the browser.",
    "shortExplanation": "Streaming turns sequential token generation into an incremental real-time network stream.",
