    "question": "What is the difference between positive constraints and negative constraints?",
    "answer": "Positive constraints specify what the model SHOULD do ('Only output valid JSON'). Negative constraints specify what it should NOT do ('Do not include markdown backticks'). Positive constraints are generally more reliable because LLMs pay attention to words mentioned in the prompt.",
