    "question": "What is Cosine Similarity and how does it measure relevance?",
    "answer": "Cosine Similarity calculates the cosine of the angle between two embedding vectors: `cos(theta) = (A . B) / (||A|| * ||B||)`. Scores range from 1.0 (identical meaning) to 0.0 (unrelated) and -1.0 (opposite). In normalized vectors, it simplifies to a fast dot product.",
    "shortExplanation": "Measures directional alignment between two vectors regardless of magnitude.",
