    "question": "Explain the ReAct (Reason + Act) loop in autonomous agents.",
    "answer": "The agent loop iterates through 4 phases: 1) Thought: The model decides what to do next based on the goal. 2) Action: The model selects a tool and outputs arguments. 3) Observation: The environment executes the tool and returns data. 4) Reflection: The model analyzes the observation and decides whether the goal is achieved or if another action is required.",
    "shortExplanation": "The ReAct loop: Thought → Action → Observation → Thought → Completion.",
